import type { Metadata } from 'next';
export const SITE_URL = 'https://www.sethpratt.com';
export const PERSON_ID = `${SITE_URL}/#seth-pratt`;
// Only the approved Vercel production build may opt in. Local/private previews stay excluded.
export const indexingEnabled = process.env.PORTFOLIO_PUBLIC_INDEXING === 'true' && process.env.VERCEL_ENV === 'production';
export function canonical(path: string) { return `${SITE_URL}${path}`; }
/** Static 1200×630 card generated by scripts/og.py for every route. */
export function ogImage(path: string) { return `/og/${path === '/' ? 'home' : path.slice(1).replace(/\//g, '-')}.jpg`; }
export function pageMetadata(path: string, title: string, description: string, opts: { absolute?: boolean; type?: 'website' | 'article' } = {}): Metadata {
  const fullTitle = opts.absolute ? title : `${title} — Seth Pratt`;
  const image = { url: ogImage(path), width: 1200, height: 630, alt: fullTitle };
  return {
    title: { absolute: fullTitle }, description,
    alternates: { canonical: canonical(path) },
    openGraph: { type: opts.type ?? 'website', locale: 'en_US', siteName: 'Seth Pratt', url: canonical(path), title: fullTitle, description, images: [image] },
    twitter: { card: 'summary_large_image', title: fullTitle, description, images: [image.url], creator: '@sethprattsf' },
  };
}
export const identityGraph = {
  '@context': 'https://schema.org', '@graph': [
    { '@type': 'Person', '@id': PERSON_ID, name: 'Seth Pratt', url: `${SITE_URL}/`,
      jobTitle: 'Applied AI Product Leader', worksFor: { '@type': 'Organization', name: 'NVIDIA' },
      image: `${SITE_URL}/images/profile.webp`,
      // Trimmed to the profiles Seth maintains, plus the app the Lab work lives in.
      sameAs: [
        'https://www.linkedin.com/in/sethpratt/',
        'https://github.com/sipratt-p',
        'https://x.com/sethprattsf',
        'https://everdust.ai',
      ],
      knowsAbout: ['AI evaluation', 'Benchmarks', 'Applied AI', 'AI agents', 'LLM inference', 'Ambient clinical documentation', 'Physics simulation'] },
    { '@type': 'WebSite', '@id': `${SITE_URL}/#website`, name: 'Seth Pratt', url: `${SITE_URL}/`, publisher: { '@id': PERSON_ID } }
  ]
};
export function breadcrumbs(items: { name: string; path: string }[]) {
  return { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: items.map((item, i) => ({
    '@type': 'ListItem', position: i + 1, name: item.name, item: canonical(item.path)
  })) };
}
